-- 管理员连接正确库后 SET ROLE lazytt_rag；仅补充注释，不更改结构或业务数据。
BEGIN;
DO $$ BEGIN
    IF current_database() <> 'rag_app' OR current_user <> 'lazytt_rag' THEN
        RAISE EXCEPTION '连接数据库或有效角色错误；管理员请先 SET ROLE lazytt_rag';
    END IF;
END $$;

