DO $$ DECLARE item record; BEGIN
    FOR item IN SELECT c.relname, pg_get_indexdef(c.oid) AS definition FROM pg_class c
      JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='rag_app' AND c.relkind='i'
    LOOP EXECUTE format('COMMENT ON INDEX %I.%I IS %L','rag_app',item.relname,
      '索引：支持其键列检索；唯一索引同时限制重复。实际定义：'||item.definition); END LOOP;
    FOR item IN SELECT c.conname, t.relname, pg_get_constraintdef(c.oid) AS definition
      FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid
      JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='rag_app'
    LOOP EXECUTE format('COMMENT ON CONSTRAINT %I ON %I.%I IS %L',item.conname,'rag_app',item.relname,
      '数据完整性约束：'||item.definition); END LOOP;
    FOR item IN SELECT t.tgname, c.relname, pg_get_triggerdef(t.oid) AS definition
      FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='rag_app' AND NOT t.tgisinternal
    LOOP EXECUTE format('COMMENT ON TRIGGER %I ON %I.%I IS %L',item.tgname,'rag_app',item.relname,
      '写入时维护记录的更新时间。实际定义：'||item.definition); END LOOP;
END $$;
COMMENT ON FUNCTION rag_app.set_updated_at() IS '更新记录时自动设置 updated_at 为事务当前时间。';
COMMENT ON SCHEMA rag_app IS 'RAG 专用数据库内的业务结构；归属 lazytt_rag，由对应版本迁移维护。';
COMMIT;
